<template><view v-if="metrics.length" class="brand-proof"><view v-for="metric in metrics" :key="metric.id"><text class="brand-proof__value">{{ metric.value }}</text><text class="brand-proof__label">{{ metric.label }}</text></view></view></template>
<script setup>import { computed } from 'vue'; const props = defineProps({ section: { type: Object, required: true } }); const metrics = computed(() => (props.section.metrics || []).filter((item) => item.enabled).sort((a, b) => a.sort - b.sort))</script>
<style scoped lang="scss">.brand-proof{display:grid;grid-template-columns:repeat(3,1fr);padding:32rpx 8rpx;background:#0d2f2b;color:#fff}.brand-proof>view{display:flex;flex-direction:column;align-items:center;border-right:1rpx solid rgba(255,255,255,.16)}.brand-proof>view:last-child{border:0}.brand-proof__value{color:#dfbb7b;font-size:31rpx;font-weight:700}.brand-proof__label{margin-top:8rpx;color:#cedbd6;font-size:20rpx;text-align:center}</style>
